module hangzo_screen_rotate
(
	input         CLK_VIDEO,
	input         CE_PIXEL,
    input         reset,
    input         pause_request,
    input         owner_drained,
    output        producer_quiescent,

	input   [7:0] VGA_R,
	input   [7:0] VGA_G,
	input   [7:0] VGA_B,
	input         VGA_HS,
	input         VGA_VS,
	input         VGA_DE,

	input         requested_ccw,
	input         requested_no_rotate,
	input         requested_flip,
	output        video_rotated,

	output            FB_EN,
	output      [4:0] FB_FORMAT,
	output reg [11:0] FB_WIDTH,
	output reg [11:0] FB_HEIGHT,
	output     [31:0] FB_BASE,
	output     [13:0] FB_STRIDE,
	input             FB_VBL,
	input             FB_LL,

	output        DDRAM_CLK,
	input         DDRAM_BUSY,
	output  [7:0] DDRAM_BURSTCNT,
	output [28:0] DDRAM_ADDR,
	output [63:0] DDRAM_DIN,
	output  [7:0] DDRAM_BE,
	output        DDRAM_WE,
	output        DDRAM_RD
);

parameter MEM_BASE    = 7'b0010010; // buffer at 0x24000000, 3x8MB


reg  do_flip=0;
reg [1:0] i_fb=1,o_fb=0,pending_fb=0;
reg pending_valid=0,display_valid=0,running=0;
reg old_frame_vs=0,old_frame_vbl=0,pause_seen=0;
reg rotate_ccw=0,no_rotate=1,flip=0;
reg  [2:0] fb_en = 0;
reg [11:0] hsz = 320, vsz = 240;
reg [11:0] bwidth=323;
reg [22:0] bufsize=0;
reg [22:0] ram_addr=0, next_addr=0;
reg [31:0] ram_data=0;
reg        ram_wr=0;
wire mode_match = requested_ccw==rotate_ccw &&
                  requested_no_rotate==no_rotate && requested_flip==flip;
wire source_boundary=CE_PIXEL && !old_frame_vs && VGA_VS;
wire consumer_boundary=!old_frame_vbl && FB_VBL;
wire frame_complete=source_boundary && running && !pause_request &&
                    mode_match && owner_drained;
wire start_frame=source_boundary && !reset && !pause_request &&
                 mode_match && owner_drained && fb_en[2] && (!no_rotate || flip);
wire writer_enabled=!reset && !pause_request && mode_match &&
                    fb_en[2] && (running || start_frame);
wire [1:0] displayed_next = consumer_boundary && (frame_complete || pending_valid)
                            ? (frame_complete ? i_fb : pending_fb) : o_fb;
wire [13:0] stride = {bwidth[11:2], 4'd0};

assign DDRAM_CLK      = CLK_VIDEO;
assign DDRAM_BURSTCNT = 1;
assign DDRAM_ADDR     = {MEM_BASE, i_fb, ram_addr[22:3]};
assign DDRAM_BE       = ram_addr[2] ? 8'hF0 : 8'h0F;
assign DDRAM_DIN      = {ram_data,ram_data};
assign DDRAM_WE       = ram_wr;
assign DDRAM_RD       = 0;

assign FB_EN     = display_valid && ( ~no_rotate || flip );
assign FB_FORMAT = 5'b00110;
assign FB_BASE   = {MEM_BASE,o_fb,23'd0};
assign FB_STRIDE = stride;

function [1:0] buf_next;
	input [1:0] a,b;
	begin
		buf_next = 1;
		if ((a==0 && b==1) || (a==1 && b==0)) buf_next = 2;
		if ((a==1 && b==2) || (a==2 && b==1)) buf_next = 0;
	end
endfunction

assign video_rotated = ~no_rotate;

always @(posedge CLK_VIDEO) begin
	do_flip <= no_rotate && flip;
	if( do_flip ) begin
		FB_WIDTH  <= hsz;
		FB_HEIGHT <= vsz;
	end else begin
		FB_WIDTH  <= vsz;
		FB_HEIGHT <= hsz;
	end
end

// Buffer publication is separate from the donor address generator. A partial
// source frame is never advertised, and repeated HDMI blanks retain the same
// complete frame. All signals here belong to CLK_VIDEO; FB_VBL must already
// obey the Template's synchronous video-domain contract at this boundary.
// ram_wr is registered by the donor. Wait a root after pause, then require
// its last pulse to have disappeared; the owner separately drains its FIFO.
assign producer_quiescent=(reset || pause_request || !mode_match || !running) &&
                          pause_seen && !ram_wr;
function [1:0] free_buffer;
    input [1:0] a,b;
    begin
        if(a!=0 && b!=0) free_buffer=0;
        else if(a!=1 && b!=1) free_buffer=1;
        else free_buffer=2;
    end
endfunction
always @(posedge CLK_VIDEO) begin
    old_frame_vbl<=FB_VBL;
    if(CE_PIXEL) old_frame_vs<=VGA_VS;
    pause_seen<=reset || pause_request || !mode_match || !running;
    if(reset) begin
        i_fb<=1;o_fb<=0;pending_fb<=0;pending_valid<=0;
        display_valid<=0;running<=0;
        rotate_ccw<=0;no_rotate<=1;flip<=0;
    end else begin
        if(pause_request || !mode_match) running<=0;
        if(!mode_match) begin pending_valid<=0;display_valid<=0;end
        if(source_boundary) begin
            running<=start_frame;
            if(owner_drained && !pause_request && !mode_match) begin
                rotate_ccw<=requested_ccw;no_rotate<=requested_no_rotate;
                flip<=requested_flip;
            end
            if(frame_complete) begin
                pending_fb<=i_fb;pending_valid<=1;
                i_fb<=free_buffer(i_fb,displayed_next);
            end
        end
        if(consumer_boundary && (frame_complete || pending_valid) && mode_match) begin
            o_fb<=displayed_next;pending_valid<=0;display_valid<=1;
        end
    end
end
// Low-latency requests use this same complete-frame publication contract.
// Deliberately retain FB_LL in the interface; unsafe partial-frame exposure
// from the donor's two-buffer branch is not enabled by it.

initial begin
	fb_en = 0;
end

always @(posedge CLK_VIDEO) begin
	reg [11:0] hcnt = 0, vcnt = 0;
	reg old_vs=0, old_de=0;

	if(CE_PIXEL) begin
		old_vs <= VGA_VS;
		old_de <= VGA_DE;

		hcnt <= hcnt + 1'd1;
		if(~old_de & VGA_DE) begin
			hcnt <= 1;
			vcnt <= vcnt + 1'd1;
		end
		if(old_de & ~VGA_DE) begin
			hsz <= hcnt;
			if( do_flip ) bwidth <= hcnt + 2'd3;
		end
		if(~old_vs & VGA_VS) begin
			vsz <= vcnt;
			if( !do_flip ) bwidth <= vcnt + 2'd3;
			vcnt <= 0;
			fb_en <= {fb_en[1:0], ~no_rotate | flip};
		end
		if(old_vs & ~VGA_VS) bufsize <= (do_flip ? vsz : hsz ) * stride;
	end
end


always @(posedge CLK_VIDEO) begin
	reg [13:0] hcnt = 0;
	reg old_vs=0, old_de=0;

	ram_wr <= 0;
    if(CE_PIXEL) begin old_vs<=VGA_VS;old_de<=VGA_DE;end
	if(CE_PIXEL && writer_enabled) begin

		if(~old_vs & VGA_VS) begin
			next_addr <=
				do_flip    ? bufsize-3'd4 :
				rotate_ccw ? (bufsize - stride) : {vsz-1'd1, 2'b00};
			hcnt <= rotate_ccw ? 3'd4 : {vsz-2'd2, 2'b00};
		end
		if(VGA_DE) begin
			ram_wr <= 1;
			ram_data <= {8'd0,VGA_B,VGA_G,VGA_R};
			ram_addr <= next_addr;
			next_addr <=
				do_flip    ? next_addr-3'd4 :
				rotate_ccw ? (next_addr - stride) : (next_addr + stride);
		end
		if(old_de & ~VGA_DE & ~do_flip) begin
			next_addr <= rotate_ccw ? (bufsize - stride + hcnt) : hcnt;
			hcnt <= rotate_ccw ? (hcnt + 3'd4) : (hcnt - 3'd4);
		end
	end
end

endmodule
